jsonTools.css:
/* Template Revise (owner-only admin): light panel, navy header with the gold rule, platinum buttons; ELI's proposal green on soft green */
._tr_root { display: flex; flex-direction: column; flex: 1 0 auto; min-height: 100%; background: #f8fafc; font: 500 12px/1.45 'Inter', sans-serif; color: #1e293b; }
._tr_head { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: linear-gradient(135deg, #0d1b2a, #1b263b); border-bottom: 3px solid #c9a227; color: #fff; }
._tr_back { border: 0; background: none; color: #fff; font: 700 15px/1 'Inter', sans-serif; cursor: pointer; padding: 0 4px; }
._tr_title { font: 700 14px/1.2 'Inter', sans-serif; letter-spacing: .02em; }
._tr_tag { margin-left: auto; font: 700 9px/1 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #fbe28a; border: 1px solid #c9a227; padding: 3px 6px; }
._tr_body { padding: 12px; display: flex; flex-direction: column; gap: 10px; }
._tr_intro { color: #475569; }
._tr_k { font: 700 9.5px/1.3 'Inter', sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #8a6d12; }
._tr_in { width: 100%; box-sizing: border-box; padding: 6px 8px; font: 500 12px/1.4 'Inter', sans-serif; color: #1e293b; border: 1px solid #cbd5e1; background: #fff; }
