._tr_list { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; background: #fff; border: 1px solid #e2e8f0; }
._tr_listtop { display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; }
._tr_pick { display: flex; align-items: center; gap: 7px; padding: 2px 0; cursor: pointer; }
._tr_link { border: 0; background: none; padding: 0; font: 600 11px/1.3 'Inter', sans-serif; color: #92400e; text-decoration: underline dotted; text-underline-offset: 2px; cursor: pointer; }
._tr_acts { display: flex; align-items: center; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
._tr_est { margin-right: auto; font-size: 11px; color: #64748b; }
._tr_btn { padding: 7px 14px; font: 700 11px/1 'Inter', sans-serif; letter-spacing: .04em; border: 1px solid #b0bcc6; color: #334155; cursor: pointer; background: linear-gradient(180deg, #ffffff 0%, #e8edf2 100%); }
._tr_btn:hover { border-color: #94a3b8; color: #0f172a; }
._tr_btn:disabled { opacity: .55; cursor: default; }
