._tr_line { font-size: 11.5px; color: #475569; }
._tr_good { font-size: 11.5px; color: #15803d; }
._tr_bad { font-size: 11.5px; color: #b42318; }
._tr_sub { padding-left: 10px; }
._tr_why { font-size: 11.5px; color: #334155; font-style: italic; }
